        putJson("/api/channels/" + p + "ch/drafts/" + DAY,
                        frameDraftBody("req-" + p + "-g2", 0, 24, 1,
                                List.of(frameSegment(p + "s1", p + "clip", 0, 1))))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.segments[0].end").value("2026-09-22T00:00:00.041+08:00"));
    }

